ALTER TABLE dynamic_entity_definitions ADD COLUMN IF NOT EXISTS revision BIGINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS dynamic_entity_definition_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,service_key VARCHAR(255) NOT NULL,tenant_key VARCHAR(255),site_key VARCHAR(255),entity_key VARCHAR(255) NOT NULL,revision BIGINT NOT NULL,status VARCHAR(40) NOT NULL,definition_json TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uk_dynamic_definition_version ON dynamic_entity_definition_versions(service_key,tenant_key,site_key,entity_key,revision);
